// VULNERABLE - input concatenated into SQL AND the raw DB error is handed to the user
try {
  db.prepare("INSERT INTO promo_claims (callsign) VALUES ('" + callsign + "')").run();
  res.send('Callsign reserved');
} catch (err) {
  res.status(400).send(err.message); // leaks: "UNIQUE constraint failed: promo_claims.callsign"
}

secureCode.code:
// SECURE - bind the value, and NEVER surface the raw DB error to the client
try {
  db.prepare('INSERT INTO promo_claims (callsign) VALUES (?)').run(callsign);
  res.send('Callsign reserved');
} catch (err) {
  logger.error('reserve_callsign_failed', err); // full detail stays server-side
  res.status(409).send('That callsign is unavailable'); // generic message leaks no schema
}

