        "INSERT INTO promo_claims (callsign) VALUES (?)")) {
    ps.setString(1, callsign);
    ps.executeUpdate();
} catch (SQLException e) {
    log.error("reserve_callsign_failed", e);            // server-side only
    return ResponseEntity.status(409).body("That callsign is unavailable");
